        "code": "# A tiny SCA engine: installed packages + dependency graph + advisory database\n\n# What is really installed (this is what a lockfile records)\nINSTALLED = {\n    \"shop-api\": \"1.0.0\",\n    \"report-engine\": \"3.2.0\",\n    \"pdf-writer\": \"1.8.4\",\n    \"log4j-core\": \"2.14.1\",\n    \"commons-text\": \"1.10.0\",\n}\n\n# Who pulls whom. The developer only wrote the first line.\nDEPENDS_ON = {\n    \"shop-api\": [\"report-engine\", \"commons-text\"],\n    \"report-engine\": [\"pdf-writer\"],\n    \"pdf-writer\": [\"log4j-core\"],\n}\n\n# Extract of a vulnerability database (real CVE identifiers)\nADVISORIES = [\n    {\"id\": \"CVE-2021-44228\", \"package\": \"log4j-core\", \"fixed_in\": \"2.15.0\", \"cvss\": 10.0},\n    {\"id\": \"CVE-2022-42889\", \"package\": \"commons-text\", \"fixed_in\": \"1.10.0\", \"cvss\": 9.8},\n]\n\n\ndef parse(version):\n    # \"2.14.1\" -> (2, 14, 1): versions must compare as numbers, not as text\n    return tuple(int(part) for part in version.split(\".\"))\n\n\ndef path_to(target, current=\"shop-api\", trail=()):\n    # Depth-first search: which chain of dependencies brings the package in?\n    trail = trail + (current,)\n    if current == target:\n        return trail\n    for child in DEPENDS_ON.get(current, []):\n        found = path_to(target, child, trail)\n        if found:\n            return found\n    return None\n\n\ndirect = DEPENDS_ON[\"shop-api\"]\nprint(f\"{len(INSTALLED) - 1} dependencies installed, {len(direct)} declared by the developer\")\n\nfor adv in ADVISORIES:\n    name = adv[\"package\"]\n    installed = INSTALLED[name]\n    if parse(installed) < parse(adv[\"fixed_in\"]):\n        print(f\"[VULNERABLE] {name} {installed} -> {adv['id']} (CVSS {adv['cvss']}), fixed in {adv['fixed_in']}\")\n        print(\"             path:\", \" > \".join(path_to(name)))\n    else:\n        print(f\"[OK]         {name} {installed} is not affected by {adv['id']}\")\n",
