        "file": "ci/audit.sh",
        "lang": "bash",
        "code": "#!/usr/bin/env bash\nset -uo pipefail          # no \"-e\": we want to run both audits, then decide\nmkdir -p reports\nstatus=0\n\n# --- web/ (Node.js) --------------------------------------------------\n# 1. Reproducible install, dependency scripts disabled\n(cd web && npm ci --ignore-scripts) || exit 1\n\n# 2. Full report for the artifact; its exit code is deliberately ignored\n(cd web && npm audit --json) > reports/npm-audit.json || true\n\n# 3. Gate: production dependencies, high and critical only\n(cd web && npm audit --omit=dev --audit-level=high) || status=1\n\n# --- api/ (Python) ---------------------------------------------------\npython -m pip install --quiet pip-audit || exit 1\n\n# Exception: PYSEC-2022-42969 (py, disputed ReDoS, no fixed version).\n# Accepted by the security team, to be reviewed every quarter.\nPIP_AUDIT_ARGS=(-r api/requirements.txt --require-hashes --disable-pip\n                --ignore-vuln PYSEC-2022-42969)\n\n# 2. Full report for the artifact\npip-audit \"${PIP_AUDIT_ARGS[@]}\" -f json -o reports/pip-audit.json || true\n\n# 4. Gate: pip-audit has no severity threshold, any known flaw fails\npip-audit \"${PIP_AUDIT_ARGS[@]}\" || status=1\n\n# 5. One global verdict for the pipeline\nexit \"$status\"\n",
